// Solo lo que el cliente escribe por WhatsApp. El chat web (inbox API) lo atiende el bot "Iagro bot".
const b = $json.body || {};
const conv = b.conversation || {};
if (b.event !== 'message_created' || b.message_type !== 'incoming' || b.private === true) return [];
if (conv.channel !== 'Channel::Whatsapp') return [];

// Botones de la plantilla de alertas ("Dejar de recibir", "ALTA"…): los atiende "IAGRO · Seguimiento de estados"
const t = String(b.content || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/^[^a-z0-9]+/, '').trim();
if (/^(dejar de recibir|no recibir alertas|desactivar alertas|activar alertas|recibir alertas|alta|solo lluvias fuertes|lluvias fuertes)$/.test(t)) return [];

// Un agente atiende el chat en Chatwoot (misma regla que el bot): etiqueta "humano",
// o asignado a un agente que lo abrió en las últimas 6 h
const etiquetas = (conv.labels || []).map((x) => String(x).toLowerCase());
const vistoAgente = Number(conv.agent_last_seen_at || 0) * 1000;
if (etiquetas.includes('humano')) return [];
if (conv.meta?.assignee && vistoAgente > Date.now() - 6 * 3600 * 1000) return [];

const sender = conv.meta?.sender || b.sender || {};
const telefono = String(sender.phone_number || '').replace(/\D/g, '');
if (telefono.length < 8 || !conv.id) return [];
return [{ json: { telefono, conversation_id: conv.id, nombre_whatsapp: String(sender.name || '').trim() } }];

// Plantilla "Ver pronóstico": {{1}} del cuerpo = nombre; {{1}} del botón = código de https://iagro360.xyz/l/{{1}}
const d = $('Solo WhatsApp entrante').first().json;
const cfg = $('Configuración').first().json.cfg || {};
const r = $json;
if (!r.enviar || !r.enlace) return [];   // ya se la mandamos hace menos de 30 min: no se repite

// WhatsApp no acepta saltos de línea ni más de 4 espacios seguidos en las variables
const limpiar = (v) => String(v ?? '').replace(/[\r\n\t]+/g, ' ').replace(/ {4,}/g, '   ').trim();
// Nombre del perfil de WhatsApp (si no es solo un número); si no, el registrado en el panel
const deWhatsapp = /[a-záéíóúñ]/i.test(d.nombre_whatsapp) ? d.nombre_whatsapp : '';
const nombre = limpiar(deWhatsapp || r.nombre_cliente || 'productor').slice(0, 60);

const base = String(cfg.chatwoot_url_publica || '').replace(/\/+$/, '') + '/api/v1/accounts/' + cfg.chatwoot_account_id;
return [{ json: {
  url: base + '/conversations/' + d.conversation_id + '/messages',
  payload: {
    // Texto que se ve en Chatwoot; a WhatsApp va la plantilla aprobada
    content: 'Hola ' + nombre + ',\n\nTu pronóstico de IAGRO 360 está listo.\n\nToca el botón para ver tu pronóstico actualizado, alertas y lluvia acumulada de tu zona.',
    message_type: 'outgoing',
    private: false,
    template_params: {
      name: cfg.plantilla_chat_web || 'pronostico_web',
      category: 'UTILITY',
      language: cfg.plantilla_idioma || 'es',
      processed_params: {
        body: { '1': nombre },
        buttons: [{ type: 'url', parameter: r.enlace }],
      },
    },
  },
} }];
